function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildPersona(f){
  f=f||{};
  var name=String(f.name||'').trim()||'匿名用户';
  var role=String(f.role||'').trim()||'（待补充）';
  var age=String(f.age||'').trim();
  var goals=splitLines(f.goals);
  var pains=splitLines(f.pains);
  var scenes=splitLines(f.scenarios);
  var quote=String(f.quote||'').trim()||'“我希望工具能帮我更高效地完成任务。”';
  var lines=[];
  lines.push('# 用户画像：'+name);
  lines.push('');
  lines.push('## 基本信息');
  lines.push('- 角色：'+role);
  if(age) lines.push('- 年龄：'+age);
  lines.push('');
  lines.push('## 目标与动机');
  if(goals.length) goals.forEach(function(g){lines.push('- '+g);}); else lines.push('（待补充）');
  lines.push('');
  lines.push('## 痛点');
  if(pains.length) pains.forEach(function(p){lines.push('- '+p);}); else lines.push('（待补充）');
  lines.push('');
  if(scenes.length){ lines.push('## 使用场景'); scenes.forEach(function(s){lines.push('- '+s);}); lines.push(''); }
  lines.push('## 代表性引言');
  lines.push(quote);
  lines.push('');
  return {title:name, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildPersona:buildPersona};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PersonaForgePure = EXPORTS; }
